{
  "findings": [
    {
      "check_id": "CKV_GCP_114",
      "title": "Ensure public access prevention is enforced on Cloud Storage bucket",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly enforce public access prevention, which could allow accidental or malicious public exposure of compliance data."
    },
    {
      "check_id": "CKV_GCP_29",
      "title": "Ensure that Cloud Storage buckets have uniform bucket-level access enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "Uniform bucket-level access is not enabled, meaning legacy ACLs might be used for access control, which is less secure and harder to audit than IAM policies."
    },
    {
      "check_id": "CKV_GCP_62",
      "title": "Bucket should log access",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "Access logging is not configured, preventing visibility into who accessed the compliance storage bucket and when, which is critical for security auditing."
    }
  ],
  "patched_code": "resource \"google_storage_bucket\" \"compliance_storage\" {\n  name     = \"${var.project_id}-digital-asset-trading-platform-compliance\"\n  location = var.region\n  versioning {\n    enabled = true\n  }\n  lifecycle_rule {\n    condition {\n      age = 2555\n    }\n    action {\n      type = \"Delete\"\n    }\n  }\n  public_access_prevention = \"enforced\"\n  uniform_bucket_level_access = true\n  logging {\n    log_bucket = google_storage_bucket.log_bucket.name\n  }\n}\n\nresource \"google_storage_bucket\" \"log_bucket\" {\n  name     = \"${var.project_id}-compliance-storage-logs\"\n  location = var.region\n  uniform_bucket_level_access = true\n}",
  "fix_summary": "Added 'public_access_prevention' set to 'enforced' and 'uniform_bucket_level_access' set to true to harden access controls. Created a dedicated log bucket and configured 'logging' on the main bucket to enable access logs, satisfying observability requirements."
}
